files.content:
:root {
  --roxo: #6546c4;
  --roxo-escuro: #472d9c;
  --lilas: #eee8ff;
  --amarelo: #ffd65a;
  --rosa: #ff8fb8;
  --azul: #5ec7f2;
  --verde: #71d6a5;
  --tinta: #28304a;
  --papel: #fffdf8;
  --sombra: 0 14px 34px rgba(57, 42, 116, 0.16);
}

/* Formas, mosaicos e medidas: extensões reutilizáveis da Cena Matemática. */
.painel-contagem-formas,
.grade-selecao-visual,
.grade-associacoes,
.campos-medidas {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 0.75rem;
}

.painel-contagem-formas {
  grid-template-columns: repeat(6, minmax(54px, 1fr));
  padding: 1rem;
  border: 2px dashed #c9b9f6;
  border-radius: 1.25rem;
  background: #fffdf8;
}

.figura-contavel,
.grade-selecao-visual button {
  min-height: 76px;
  border: 2px solid #ded5f7;
  border-radius: 1rem;
  background: #fff;
  color: #34266d;
}

.figura-contavel[aria-pressed='true'],
.grade-selecao-visual button[aria-pressed='true'] {
  border-color: #4f34b5;
  background: #eee9ff;
  box-shadow: inset 0 0 0 3px #fff;
}

.grade-selecao-visual button {
  display: grid;
  place-items: center;
  gap: 0.4rem;
  padding: 0.85rem;
}

.forma-geometrica {
  position: relative;
  display: inline-block;
  width: 52px;
  height: 52px;
  flex: 0 0 auto;
}

.forma-circulo {
  border: 3px solid #3579b7;
  border-radius: 50%;
  background: #9ed8ff;
}

.forma-quadrado,
.forma-retangulo {
  border: 3px solid #30886f;
  border-radius: 0.35rem;
  background: #94dfc8;
}

.forma-retangulo {
  width: 68px;
  height: 44px;
}

.forma-triangulo {
  width: 0;
  height: 0;
  border-right: 30px solid transparent;
  border-bottom: 52px solid #f5a45d;
  border-left: 30px solid transparent;
  filter: drop-shadow(0 3px 0 #aa5b26);
}

.forma-cone {
  width: 0;
  height: 0;
  border-right: 25px solid transparent;
  border-bottom: 48px solid #f3bf54;
  border-left: 25px solid transparent;
}

.forma-cone::after {
  position: absolute;
  top: 42px;
  left: -26px;
  width: 52px;
  height: 13px;
  border: 3px solid #9d6610;
  border-radius: 50%;
  background: #ffd77d;
  content: '';
}

.painel-forma-detalhe,
.painel-visual-medidas {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 120px;
  margin-bottom: 1rem;
  padding: 1rem;
  gap: 1rem;
  border: 2px solid #ded5f7;
  border-radius: 1.25rem;
  background: linear-gradient(135deg, #fff8dc, #f1edff);
  color: #3f2b91;
  font-size: 1.2rem;
  text-align: center;
}

.painel-forma-detalhe .forma-geometrica {
  transform: scale(1.35);
  margin: 0.75rem;
}

.campo-medida,
.cartao-associacao {
  display: grid;
  align-content: center;
  min-height: 112px;
  padding: 1rem;
  gap: 0.65rem;
  border: 2px solid #ded5f7;
  border-radius: 1rem;
  background: #fff;
  color: #2e235d;
  font-weight: 700;
}

.entrada-com-unidade {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.entrada-com-unidade input,
.cartao-associacao select {
  width: 100%;
  min-height: 46px;
  border: 2px solid #8065d4;
  border-radius: 0.75rem;
  background: #fff;
  color: #24184f;
  font: inherit;
}

.entrada-com-unidade input {
  min-width: 0;
  padding: 0.5rem 0.75rem;
}

.cartao-associacao {
  justify-items: start;
}

.cartao-associacao .simbolo-medida {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 0.85rem;
  background: #fff1b9;
  color: #3f2b91;
  font-size: 2rem;
}

/* Questão 7 de "Formas, mosaicos e medidas": objetos reconhecíveis sem dar a resposta em texto. */
.cartao-associacao:has([data-math-visual-select='bandeira']) .simbolo-medida,
.cartao-associacao:has([data-math-visual-select='cone']) .simbolo-medida {
  position: relative;
  width: 68px;
  height: 68px;
  overflow: hidden;
  font-size: 0;
}

.cartao-associacao:has([data-math-visual-select='bandeira']) .simbolo-medida::before {
  position: absolute;
  top: 8px;
  left: 13px;
  width: 5px;
  height: 52px;
  border-radius: 999px;
  background: linear-gradient(90deg, #51339b, #a58be8 50%, #51339b);
  box-shadow: 0 2px 3px rgb(54 35 111 / 28%);
  content: '';
}

.cartao-associacao:has([data-math-visual-select='bandeira']) .simbolo-medida::after {
  position: absolute;
  top: 11px;
  left: 17px;
  width: 43px;
  height: 35px;
  background:
    linear-gradient(135deg, rgb(255 255 255 / 58%), transparent 42%),
    linear-gradient(90deg, #ff8e6c, #ed4775);
  clip-path: polygon(0 0, 100% 50%, 0 100%);
  filter: drop-shadow(0 2px 2px rgb(81 51 155 / 28%));
  content: '';
}

.cartao-associacao:has([data-math-visual-select='cone']) .simbolo-medida::before {
  position: absolute;
  top: 7px;
  left: 17px;
  width: 34px;
  height: 46px;
  background:
    linear-gradient(to bottom, transparent 0 42%, #fff8e8 42% 59%, transparent 59% 100%),
    linear-gradient(90deg, #d45c0c, #ff9e2f 32%, #ffc05b 56%, #df6810);
  clip-path: polygon(45% 0, 55% 0, 92% 100%, 8% 100%);
  filter: drop-shadow(0 2px 2px rgb(116 55 12 / 24%));
  content: '';
}

.cartao-associacao:has([data-math-visual-select='cone']) .simbolo-medida::after {
  position: absolute;
  bottom: 7px;
  left: 7px;
  width: 54px;
  height: 13px;
  border: 3px solid #9e4709;
  border-radius: 48% 48% 30% 30% / 62% 62% 35% 35%;
  background: linear-gradient(#ffb347, #dc610e);
  box-shadow:
    inset 0 3px rgb(255 222 153 / 55%),
    0 3px 3px rgb(116 55 12 / 24%);
  content: '';
}

.painel-capacidade,
.painel-mercado {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  margin-bottom: 1rem;
  padding: 1rem;
  gap: 0.75rem;
  border: 2px solid #ded5f7;
  border-radius: 1.25rem;
  background: linear-gradient(135deg, #fffaf0, #f1edff);
}

.grupo-capacidade,
.cartao-produto {
  display: grid;
  place-items: center;
  align-content: center;
  min-height: 124px;
  padding: 0.75rem;
  gap: 0.4rem;
  border: 2px solid #e5dcfa;
  border-radius: 1rem;
  background: #fff;
  color: #332568;
  text-align: center;
}

.grupo-capacidade > span,
.cartao-produto > span:last-child {
  color: #66568d;
  font-size: 0.92rem;
}

.serie-recipientes {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: center;
  min-height: 62px;
  gap: 0.25rem;
}

.recipiente-visual {
  position: relative;
  display: inline-block;
  width: 48px;
  height: 58px;
  flex: 0 0 auto;
}

.recipiente-visual > span,
.recipiente-visual > i,
.recipiente-visual > b {
  position: absolute;
  display: block;
  box-sizing: border-box;
}

.recipiente-copo > span {
  inset: 11px 7px 3px;
  border: 3px solid #4b75a7;
  border-radius: 0.25rem 0.25rem 0.8rem 0.8rem;
  background: linear-gradient(to top, #76ccef 0 55%, #eaf9ff 55%);
  clip-path: polygon(4% 0, 96% 0, 83% 100%, 17% 100%);
}

.recipiente-jarra > span {
  inset: 10px 7px 3px 5px;
  border: 3px solid #4b75a7;
  border-radius: 0.45rem 0.75rem 0.8rem 0.8rem;
  background: linear-gradient(to top, #76ccef 0 58%, #eefaff 58%);
  clip-path: polygon(0 14%, 78% 14%, 100% 0, 93% 100%, 6% 100%);
}

.recipiente-jarra > i {
  top: 19px;
  right: -1px;
  width: 18px;
  height: 28px;
  border: 4px solid #4b75a7;
  border-left: 0;
  border-radius: 0 50% 50% 0;
}

.recipiente-garrafa > span,
.recipiente-galao > span,
.recipiente-frasco > span {
  right: 8px;
  bottom: 3px;
  left: 8px;
  height: 42px;
  border: 3px solid #3f729e;
  border-radius: 0.8rem 0.8rem 0.55rem 0.55rem;
  background: linear-gradient(to top, #7fd6ee 0 62%, #effcff 62%);
}

.recipiente-garrafa > i,
.recipiente-galao > i,
.recipiente-frasco > i {
  top: 3px;
  left: 17px;
  width: 15px;
  height: 16px;
  border: 3px solid #3f729e;
  border-radius: 0.25rem 0.25rem 0 0;
  background: #eefcff;
}

.recipiente-galao > span {
  right: 2px;
  left: 2px;
  border-radius: 1rem 1rem 0.65rem 0.65rem;
}

.recipiente-galao > b {
  top: 18px;
  right: 7px;
  width: 14px;
  height: 18px;
  border: 3px solid #3f729e;
  border-radius: 50%;
  background: #fff;
}

.recipiente-caixa > span {
  inset: 6px 7px 3px;
  border: 3px solid #b05b66;
  border-radius: 0.35rem;
  background: linear-gradient(135deg, #ffb88f 0 48%, #ff8f9d 48%);
  clip-path: polygon(12% 0, 88% 0, 100% 14%, 100% 100%, 0 100%, 0 14%);
}

.recipiente-caixa > i {
  top: 0;
  right: 9px;
  width: 4px;
  height: 19px;
  transform: rotate(12deg);
  border-radius: 999px;
  background: #6d4c9f;
}

.recipiente-balde > span {
  inset: 17px 4px 3px;
  border: 3px solid #7250a4;
  border-radius: 0.35rem 0.35rem 0.9rem 0.9rem;
  background: linear-gradient(to top, #91d8f4 0 62%, #f1fbff 62%);
  clip-path: polygon(0 0, 100% 0, 85% 100%, 15% 100%);
}

.recipiente-balde > i {
  top: 4px;
  left: 8px;
  width: 32px;
  height: 25px;
  border: 3px solid #7250a4;
  border-bottom: 0;
  border-radius: 50% 50% 0 0;
}

.recipiente-xicara > span {
  inset: 18px 10px 5px 3px;
  border: 3px solid #a85f69;
  border-radius: 0.3rem 0.3rem 1rem 1rem;
  background: linear-gradient(to top, #f2b877 0 68%, #fff8e8 68%);
}

.recipiente-xicara > i {
  top: 23px;
  right: 1px;
  width: 16px;
  height: 20px;
  border: 4px solid #a85f69;
  border-left: 0;
  border-radius: 0 50% 50% 0;
}

.recipiente-frasco {
  transform: scale(0.78);
}

.equacao-capacidade {
  margin: 0 0 1rem;
  padding: 0.8rem 1rem;
  border: 2px dashed #8d73d6;
  border-radius: 1rem;
  background: #fff;
  color: #3f2b91;
  font-size: 1.08rem;
  font-weight: 900;
  text-align: center;
}

.painel-operacao-du {
  display: grid;
  grid-template-columns: minmax(190px, 260px) minmax(180px, 1fr);
  align-items: center;
  margin-bottom: 1rem;
  padding: 1rem;
  gap: 1rem;
  border: 2px solid #d9cff6;
  border-radius: 1.25rem;
  background: linear-gradient(135deg, #fff8dc, #f1edff);
}

.painel-operacao-du table {
  width: 100%;
  border: 3px solid #5940b2;
  border-collapse: separate;
  border-spacing: 0;
  border-radius: 0.8rem;
  background: #fff;
  color: #2f225f;
  font-size: 1.35rem;
  text-align: center;
}

.painel-operacao-du caption {
  padding: 0.55rem;
  color: #3f2b91;
  font-size: 1rem;
  font-weight: 900;
}

.painel-operacao-du th,
.painel-operacao-du td {
  width: 33.33%;
  padding: 0.45rem;
  border-top: 1px solid #d9cff6;
  border-left: 1px solid #d9cff6;
}

.painel-operacao-du tr > :first-child {
  border-left: 0;
}

.painel-operacao-du p {
  margin: 0;
  color: #483778;
  font-weight: 800;
  line-height: 1.5;
}

.cartao-produto {
  min-height: 142px;
}

.produto-visual {
  position: relative;
  display: inline-block;
  width: 58px;
  height: 62px;
}

.produto-visual > span,
.produto-visual > i,
.produto-visual > b {
  position: absolute;
  display: block;
  box-sizing: border-box;
}

.produto-pacote > span,
.produto-caixa > span {
  inset: 6px 8px 3px;
  border: 3px solid #8654a8;
  border-radius: 0.45rem;
  background: linear-gradient(135deg, #ffd166 0 45%, #ef8fb6 45%);
  clip-path: polygon(8% 0, 92% 0, 100% 10%, 95% 100%, 5% 100%, 0 10%);
}

.produto-pacote > i,
.produto-caixa > i,
.produto-lata > i {
  top: 25px;
  left: 17px;
  width: 24px;
  height: 14px;
  border: 2px solid #fff;
  border-radius: 999px;
  background: #6f4bb2;
}

.produto-caixa > span {
  background: linear-gradient(135deg, #9ee1c9 0 50%, #6fbce8 50%);
  clip-path: polygon(12% 0, 88% 0, 100% 13%, 100% 100%, 0 100%, 0 13%);
}

.produto-lata > span {
  inset: 8px 11px 3px;
  border: 3px solid #486b91;
  border-radius: 45% 45% 25% 25% / 12% 12% 8% 8%;
  background: linear-gradient(90deg, #9fd4ef, #e8f8ff 48%, #79b5d8);
}

.produto-ovos > span {
  right: 2px;
  bottom: 7px;
  left: 2px;
  height: 30px;
  border: 3px solid #9a713b;
  border-radius: 0.8rem;
  background:
    radial-gradient(ellipse at 18% 40%, #fff3d5 0 13%, transparent 14%),
    radial-gradient(ellipse at 50% 40%, #fff3d5 0 13%, transparent 14%),
    radial-gradient(ellipse at 82% 40%, #fff3d5 0 13%, transparent 14%), #d9ab68;
}

.regua-interativa {
  position: relative;
  max-width: 100%;
  margin-bottom: 1rem;
  padding: 3rem 1rem 1rem;
  overflow-x: auto;
  border: 2px solid #c69d35;
  border-radius: 1rem;
  background: #ffe08a;
  color: #4e3810;
}

.regua-interativa .objeto-na-regua {
  position: absolute;
  top: 1rem;
  left: 1rem;
  width: calc((100% - 2rem) * var(--fim) / var(--divisoes));
  height: 1.1rem;
  border-radius: 999px 30% 30% 999px;
  background: #4f34b5;
}

.marcas-regua {
  display: grid;
  grid-template-columns: repeat(var(--divisoes), minmax(16px, 1fr)) 0;
  min-width: calc(var(--divisoes) * 17px);
}

.marcas-regua span {
  position: relative;
  height: 46px;
  border-left: 1px solid #72551d;
}

.marcas-regua span:last-child {
  border-right: 1px solid #72551d;
}

.marcas-regua span i {
  display: block;
  height: 15px;
}

.marcas-regua .marca-maior i {
  height: 26px;
}

.marcas-regua small {
  display: none;
  transform: translateX(-50%);
}

.marcas-regua .marca-maior small,
.marcas-regua span:last-child small {
  display: block;
}

.paleta-mosaico {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 1rem;
  gap: 0.65rem;
}

.paleta-mosaico button {
  display: flex;
  align-items: center;
  min-height: 48px;
  padding: 0.5rem 0.8rem;
  gap: 0.45rem;
  border: 2px solid #a792e5;
  border-radius: 0.8rem;
  background: #fff;
  color: #34266d;
  font-weight: 800;
}

.paleta-mosaico button[aria-pressed='true'] {
  outline: 4px solid #4f34b5;
  outline-offset: 2px;
}

.paleta-mosaico button span {
  width: 28px;
  height: 28px;
  border: 2px solid #55427f;
  border-radius: 0.4rem;
  background: var(--cor-mosaico);
}

.grade-mosaico {
  display: grid;
  grid-template-columns: repeat(var(--colunas-mosaico), minmax(40px, 1fr));
  max-width: 560px;
  margin: 0 auto;
  gap: 0.35rem;
}

.celula-mosaico {
  aspect-ratio: 1;
  min-height: 42px;
  border: 2px dashed #927bd7;
  border-radius: 0.45rem;
  background: #fff;
}

.celula-mosaico.fixa {
  border-style: solid;
  box-shadow: inset 0 0 0 3px rgb(255 255 255 / 55%);
}

.celula-mosaico.cor-amarelo {
  background: #ffd166;
}

.celula-mosaico.cor-azul {
  background: #72b7ff;
}

.celula-mosaico.cor-rosa {
  background: #ef8fb6;
}

.orientacao-mosaico {
  margin: 0.8rem 0 0;
  color: #584a83;
  text-align: center;
}

.balanca-visual {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: end;
  min-height: 210px;
  margin-bottom: 1rem;
  padding: 1rem 1rem 3rem;
  gap: 3rem;
  border-radius: 1.25rem;
  background: #fff8dc;
}

.prato {
  position: relative;
  z-index: 2;
  display: grid;
  place-items: center;
  min-height: 68px;
  border-bottom: 10px solid #9f7531;
  border-radius: 50%;
  background: #fff;
  color: #3f2b91;
  font-weight: 800;
}

.prato-esquerdo {
  transform: translateY(25px);
}

.haste-balanca {
  position: absolute;
  bottom: 75px;
  left: 15%;
  width: 70%;
  height: 8px;
  transform: rotate(-5deg);
  border-radius: 999px;
  background: #6c542d;
}

.base-balanca {
  position: absolute;
  bottom: 20px;
  left: 50%;
  width: 90px;
  height: 70px;
  transform: translateX(-50%);
  border-radius: 50% 50% 0 0;
  background: #7d64c7;
}

@media (max-width: 560px) {
  .painel-contagem-formas {
    grid-template-columns: repeat(3, minmax(52px, 1fr));
  }

  .grade-mosaico {
    grid-template-columns: repeat(var(--colunas-mosaico), minmax(34px, 1fr));
  }

  .celula-mosaico {
    min-height: 36px;
  }

  .balanca-visual {
    gap: 1rem;
  }

  .painel-capacidade,
  .painel-mercado {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 0.65rem;
  }

  .grupo-capacidade,
  .cartao-produto {
    min-height: 116px;
    padding: 0.55rem;
  }

  .recipiente-visual {
    transform: scale(0.88);
    margin: -3px;
  }

  .recipiente-frasco {
    transform: scale(0.7);
  }

  .painel-operacao-du {
    grid-template-columns: 1fr;
  }
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 280px;
  overflow-x: clip;
  color: var(--tinta);
  background: #f6f3ff;
  font-family: 'Trebuchet MS', 'Segoe UI', sans-serif;
  line-height: 1.5;
}

button,
input {
  font: inherit;
}

button {
  color: inherit;
}

button:focus-visible,
input:focus-visible,
canvas:focus-visible {
  outline: 4px solid var(--amarelo);
  outline-offset: 3px;
}

.topo {
  position: sticky;
  z-index: 10;
  top: 0;
  display: grid;
  grid-template-columns: 48px 1fr auto;
  gap: 12px;
  align-items: center;
  min-height: 76px;
  padding: 10px clamp(16px, 5vw, 64px);
  color: white;
  background: linear-gradient(120deg, var(--roxo-escuro), var(--roxo));
  box-shadow: 0 5px 20px rgba(46, 29, 105, 0.2);
}

.marca {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: clamp(1rem, 3vw, 1.3rem);
  font-weight: 900;
}

.marca img {
  padding: 7px;
  border-radius: 14px;
  background: white;
}

.botao-icone {
  width: 44px;
  height: 44px;
  border: 2px solid rgba(255, 255, 255, 0.45);
  border-radius: 50%;
  color: white;
  background: rgba(255, 255, 255, 0.15);
  cursor: pointer;
  font-size: 1.8rem;
}

.botao-icone[hidden] {
  display: block !important;
  visibility: hidden;
  pointer-events: none;
}

.progresso-resumo {
  padding: 7px 13px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.17);
  font-size: 0.88rem;
  font-weight: 800;
}

.acoes-topo {
  display: flex;
  gap: 8px;
  align-items: center;
}

.limpar-progresso {
  padding: 6px 10px;
  border: 1px solid rgba(255, 255, 255, 0.45);
  border-radius: 999px;
  color: white;
  background: transparent;
  cursor: pointer;
  font-size: 0.72rem;
}

main {
  min-height: calc(100vh - 140px);
}

.tela {
