.nuvem {
  position: absolute;
  width: 160px;
  height: 48px;
  border-radius: 999px;
  opacity: 0.5;
  background: white;
}

.nuvem::before,
.nuvem::after {
  position: absolute;
  content: '';
  border-radius: 50%;
  background: inherit;
}

.nuvem::before {
  top: -36px;
  left: 34px;
  width: 76px;
  height: 76px;
}

.nuvem::after {
  top: -22px;
  right: 22px;
  width: 58px;
  height: 58px;
}

.nuvem-1 {
  top: 12%;
  left: 2%;
}

.nuvem-2 {
