/*
 * Capacidade opt-in para revisões que aproveitam monitores desktop largos.
 * A classe é aplicada pelo controlador somente quando a unidade declara
 * layout.desktopAmplo, preservando integralmente as revisões legadas.
 */
@media (min-width: 1120px) {
  .tela-ingles.layout-desktop-amplo {
    --espaco-desktop-amplo: clamp(20px, 2vw, 34px);
    --coluna-estudo-desktop-amplo: clamp(330px, 25vw, 430px);

    width: min(2360px, 94vw);
  }

  .layout-desktop-amplo .cabecalho-ingles > div > p:last-child {
    max-width: 1000px;
  }

  .layout-desktop-amplo .painel-audio-ingles {
    display: grid;
    grid-template-areas:
      'titulo vozes'
      'controles status';
    grid-template-columns: minmax(0, 1.45fr) minmax(320px, 0.75fr);
    gap: 18px var(--espaco-desktop-amplo);
  }

  .layout-desktop-amplo .cabecalho-painel-audio {
    display: contents;
  }

  .layout-desktop-amplo .cabecalho-painel-audio > div {
    grid-area: titulo;
  }

  .layout-desktop-amplo .vozes-locais {
    grid-area: vozes;
    max-width: none;
  }

  .layout-desktop-amplo .controles-audio-ingles {
    grid-area: controles;
    align-content: start;
  }

  .layout-desktop-amplo .status-audio-ingles {
    grid-area: status;
    align-self: stretch;
    margin-top: 0;
  }

  .layout-desktop-amplo .grupos-ingles {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  }

  .layout-desktop-amplo .aba-grupo-ingles {
    width: 100%;
  }

  .layout-desktop-amplo .conteudo-grupo-ingles {
    display: grid;
    grid-template-areas:
      'resumo grade'
      'escrita grade';
    grid-template-columns: var(--coluna-estudo-desktop-amplo) minmax(0, 1fr);
    gap: 18px var(--espaco-desktop-amplo);
    align-items: start;
  }

  .layout-desktop-amplo .cabecalho-grupo-ingles {
    grid-area: resumo;
    grid-template-columns: 1fr;
    gap: 18px;
    margin-bottom: 0;
  }

  .layout-desktop-amplo .pratica-escrita-ingles {
    grid-area: escrita;
    margin-bottom: 0;
  }

  .layout-desktop-amplo .grade-palavras-ingles {
    grid-area: grade;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  }

  .layout-desktop-amplo .cena-story-time-ingles {
    grid-template-columns: minmax(360px, 0.9fr) minmax(0, 1.1fr);
  }

  .layout-desktop-amplo #ingles-cartao-questao.com-apoio-visual {
    display: grid;
    grid-template-areas:
      'cabecalho cabecalho'
      'pergunta imagens'
      'traducao imagens'
      'alternativas imagens'
      'status status'
      'navegacao navegacao';
    grid-template-columns: minmax(0, 1fr) minmax(260px, 0.38fr);
    column-gap: var(--espaco-desktop-amplo);
    align-items: start;
  }

  .layout-desktop-amplo #ingles-cartao-questao.com-apoio-visual .cabecalho-atividade-ingles {
    grid-area: cabecalho;
  }

  .layout-desktop-amplo #ingles-cartao-questao.com-apoio-visual .imagens-enunciado-ingles {
    grid-area: imagens;
    align-self: stretch;
    align-content: center;
    margin: 0;
  }

  .layout-desktop-amplo #ingles-cartao-questao.com-apoio-visual #ingles-pergunta-atividade {
    grid-area: pergunta;
  }

  .layout-desktop-amplo #ingles-cartao-questao.com-apoio-visual .traducao-pergunta-ingles {
    grid-area: traducao;
  }

  .layout-desktop-amplo #ingles-cartao-questao.com-apoio-visual .alternativas-atividade-ingles {
    grid-area: alternativas;
  }

  .layout-desktop-amplo #ingles-cartao-questao.com-apoio-visual .status-atividade-ingles {
    grid-area: status;
  }

  .layout-desktop-amplo #ingles-cartao-questao.com-apoio-visual .navegacao-atividade-ingles {
    grid-area: navegacao;
  }

  .layout-desktop-amplo #ingles-lista-revisao {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

