}

.palavra-glossario:hover {
  color: #33206e;
  background: #f2edff;
}

.palavra-glossario:focus-visible,
.fechar-dialogo-glossario:focus-visible {
  outline: 4px solid var(--amarelo);
  outline-offset: 3px;
}

.atalhos-glossario {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
  width: fit-content;
  margin: 12px 0 20px;
  padding: 10px 14px;
  border: 2px solid #e2d9fb;
  border-radius: 14px;
  color: #514a66;
  background: #faf8ff;
  font-weight: 800;
}

.dialogo-glossario {
  width: min(620px, calc(100% - 28px));
  max-height: min(720px, calc(100% - 28px));
  padding: 0;
  overflow: auto;
  border: 0;
  border-radius: 24px;
  color: var(--texto);
  background: white;
  box-shadow: 0 24px 70px rgba(34, 29, 54, 0.35);
}

.dialogo-glossario::backdrop {
  background: rgba(34, 29, 54, 0.58);
  backdrop-filter: blur(3px);
}

.cartao-dialogo-glossario {
  padding: clamp(20px, 5vw, 34px);
}

.cabecalho-dialogo-glossario {
  display: flex;
  gap: 18px;
  justify-content: space-between;
  align-items: start;
  margin-bottom: 18px;
}

.cabecalho-dialogo-glossario h2 {
  margin: 0;
  color: var(--roxo-escuro);
  font-size: clamp(1.7rem, 5vw, 2.35rem);
}

.fechar-dialogo-glossario {
  flex: 0 0 auto;
  width: 48px;
  min-height: 48px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  color: var(--roxo-escuro);
  background: var(--lilas);
  cursor: pointer;
  font-size: 2rem;
  line-height: 1;
}

.verbete-glossario + .verbete-glossario {
  margin-top: 18px;
  padding-top: 18px;
  border-top: 2px solid #ece7f7;
}

.verbete-glossario h3 {
  margin: 0 0 8px;
  color: var(--roxo-escuro);
  font-size: 1.35rem;
}

.verbete-glossario p {
  margin: 9px 0 0;
  font-size: clamp(1rem, 2.5vw, 1.15rem);
  line-height: 1.6;
}

.verbete-glossario p:last-child {
  padding: 12px 14px;
  border-radius: 13px;
  background: #fff7d5;
}

.controles-zoom,
.ir-para-pagina {
  display: flex;
  gap: 8px;
  align-items: center;
}

.controles-zoom output {
  min-width: 58px;
  text-align: center;
  font-weight: 900;
}

.botao-quadrado {
  width: 46px;
  min-height: 46px;
  padding: 5px;
  font-size: 1.35rem;
}

.ir-para-pagina {
  margin-left: auto;
  font-weight: 900;
}

.ir-para-pagina input {
  width: 76px;
  min-height: 46px;
  padding: 7px;
  border: 3px solid #dcd2f7;
  border-radius: 12px;
  text-align: center;
  font-weight: 900;
}

.recipiente-canvas-livro {
  position: relative;
  display: grid;
  width: 100%;
  min-height: 280px;
  overflow: auto;
  place-items: start center;
  padding: 12px;
  border-radius: 18px;
  background: #dedbe6;
  overscroll-behavior: contain;
}

.canvas-livro {
  display: block;
  max-width: none;
  height: auto;
  background: white;
  box-shadow: 0 5px 18px rgba(34, 29, 54, 0.2);
}

.estado-pdf,
.erro-pdf {
  position: absolute;
  z-index: 2;
  inset: 50% auto auto 50%;
  width: min(520px, calc(100% - 32px));
  padding: 18px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 7px 18px rgba(34, 29, 54, 0.16);
  transform: translate(-50%, -50%);
  text-align: center;
  font-weight: 900;
}

.erro-pdf {
  width: min(680px, calc(100% - 32px));
  color: #7b1b1b;
  background: #ffe8e8;
}

.erro-pdf span {
  display: block;
  margin-top: 6px;
}

.acoes-erro-pdf {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  margin-top: 16px;
}

.acoes-erro-pdf button {
  min-height: 48px;
}

.erro-pdf small {
  display: block;
  margin-top: 14px;
  color: #5e3838;
  font-weight: 700;
}

.descricao-canvas-livro,
.alternativa-pdf {
  margin: 10px 0 0;
  color: #625b75;
  font-size: 0.92rem;
}

.alternativa-pdf {
  text-align: center;
}

.alternativa-pdf a {
  color: var(--roxo-escuro);
  font-weight: 900;
}

.navegacao-paginas-leitura,
.navegacao-questionario-leitura {
  display: flex;
  gap: 16px;
  justify-content: space-between;
  margin-top: 20px;
}

.explicacao-final-leitura {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 0.9fr);
  gap: clamp(20px, 4vw, 38px);
  align-items: center;
  margin-top: 28px;
  padding: clamp(22px, 4vw, 38px);
  border: 3px solid #dfd6fa;
  border-radius: 30px;
  background: linear-gradient(145deg, #fffef4, #f0ebff);
  box-shadow: var(--sombra);
}

.explicacao-final-leitura[hidden] {
  display: none;
}

.explicacao-final-leitura h2 {
  margin-bottom: 14px;
  color: var(--roxo-escuro);
  font-size: clamp(1.55rem, 3.5vw, 2.25rem);
}

.texto-explicacao-final-leitura > div {
  display: grid;
  gap: 12px;
}

.texto-explicacao-final-leitura p {
  margin: 0;
  line-height: 1.65;
}

.texto-explicacao-final-leitura .chapeu {
  margin-bottom: 8px;
}

.aviso-seguranca-eclipse {
  padding: 14px 16px;
  border-left: 6px solid #f2b705;
  border-radius: 12px;
  background: #fff5c7;
  color: #4b3a00;
  font-weight: 800;
}

.explicacao-final-leitura img {
  display: block;
  width: 100%;
  height: auto;
  border: 4px solid white;
  border-radius: 24px;
  box-shadow: 0 14px 32px rgba(49, 29, 104, 0.2);
}

.botao-terminar-leitura {
  display: block;
  width: min(560px, 100%);
  min-height: 62px;
  margin: 22px auto 0;
  font-size: 1.12rem;
}

.somente-leitor-tela {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

.progresso-questionario-leitura {
  height: 16px;
  overflow: hidden;
  margin-bottom: 22px;
  border-radius: 999px;
  background: #e9e2ff;
}

.progresso-questionario-leitura span {
  display: block;
  width: 10%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ff8fb8, #ffd65a, #71d6a5);
  transition: width 0.25s ease;
}

.cartao-pergunta-leitura,
.resultado-leitura,
.revisao-questionario-leitura {
  padding: clamp(24px, 5vw, 46px);
  border: 3px solid white;
  border-radius: 30px;
  background: white;
  box-shadow: var(--sombra);
}

.cartao-pergunta-leitura h2 {
  max-width: 850px;
  font-size: clamp(1.55rem, 4vw, 2.35rem);
}

.aviso-correcao-em-lote {
  max-width: 820px;
  margin: 14px 0 0;
  padding: 12px 16px;
  border: 2px solid #cfc1f3;
  border-radius: 14px;
  color: #514a66;
  background: #f7f3ff;
  font-weight: 800;
}

.revisao-questionario-leitura > h2 {
  margin: 0 0 8px;
  font-size: clamp(1.9rem, 5vw, 2.8rem);
}

.resumo-revisao-questionario {
  margin: 0;
  color: var(--roxo-escuro);
  font-size: clamp(1.2rem, 3vw, 1.55rem);
  font-weight: 900;
}

.lista-revisao-questionario {
  display: grid;
  gap: 16px;
  margin: 28px 0;
}

.item-revisao-questionario {
  padding: clamp(17px, 3vw, 24px);
  border: 3px solid #d8d0ed;
  border-radius: 20px;
  background: #fcfbff;
}

.item-revisao-questionario.correta {
  border-color: #218b5d;
  background: #effbf5;
}

.item-revisao-questionario.incorreta {
  border-color: #d94d73;
  background: #fff4f7;
}

.item-revisao-questionario h3 {
  margin: 8px 0 12px;
  font-size: clamp(1.1rem, 3vw, 1.35rem);
}

.status-item-revisao,
.resposta-item-revisao,
.resposta-certa-revisao,
.explicacao-item-revisao {
  margin: 8px 0;
}

.status-item-revisao,
.resposta-certa-revisao {
  color: var(--roxo-escuro);
  font-weight: 900;
}

.item-revisao-questionario.correta .status-item-revisao {
  color: #176c47;
}

.item-revisao-questionario.incorreta .status-item-revisao {
  color: #a52d50;
}

.explicacao-item-revisao {
  padding: 12px 14px;
  border-radius: 12px;
  background: white;
}

.continuar-ditados {
  min-width: min(100%, 300px);
}

.opcoes-leitura {
  display: grid;
  gap: 13px;
  margin: 24px 0;
}

.atividade-ditado {
  display: grid;
  max-width: 820px;
  gap: 14px;
  margin: 24px 0;
  padding: clamp(18px, 4vw, 28px);
  border: 3px solid #dfd6fa;
  border-radius: 20px;
  background: #fcfbff;
}

.atividade-ditado p {
  margin: 0;
  color: #514a66;
  font-weight: 800;
}

.atividade-ditado label {
  margin-top: 4px;
  color: var(--roxo-escuro);
  font-weight: 900;
}

.botao-ouvir-ditado {
  width: fit-content;
  min-height: 52px;
  font-size: 1.05rem;
}

.entrada-ditado {
  width: 100%;
  min-height: 58px;
  padding: 12px 15px;
  border: 3px solid #cfc1f3;
  border-radius: 14px;
  outline: none;
  background: white;
  font-size: clamp(1rem, 2.5vw, 1.2rem);
  font-weight: 800;
}

.entrada-ditado:focus {
  border-color: var(--roxo);
  box-shadow: 0 0 0 4px rgba(92, 61, 184, 0.18);
}

.entrada-ditado.correta {
  border-color: #218b5d;
  background: #dcf8e9;
}

.entrada-ditado.incorreta {
  border-color: #d94d73;
  background: #ffe2ea;
}

.opcao-leitura {
  display: flex;
  gap: 13px;
  align-items: center;
  width: 100%;
  min-height: 62px;
  padding: 13px 17px;
  border: 3px solid #dfd6fa;
  border-radius: 18px;
  text-align: left;
  background: #fcfbff;
  cursor: pointer;
  font-size: clamp(1rem, 2.3vw, 1.25rem);
  font-weight: 900;
}

.opcao-leitura:hover,
.opcao-leitura.selecionada {
  border-color: var(--roxo);
  background: var(--lilas);
}

.opcao-leitura.correta {
  border-color: #218b5d;
  background: #dcf8e9;
}

.opcao-leitura.incorreta {
  border-color: #d94d73;
  background: #ffe2ea;
}

.retorno-pergunta-leitura {
  min-height: 54px;
  padding-top: 4px;
}

.resultado-leitura {
  display: grid;
  justify-items: center;
  text-align: center;
}

.trofeu-leitura {
  display: grid;
  width: 96px;
  height: 96px;
  place-items: center;
  border-radius: 50%;
  color: #765000;
  background: var(--amarelo);
  box-shadow: 0 7px 0 #e5ae26;
  font-size: 3.6rem;
}

.resultado-leitura h2 {
  margin: 26px 0 6px;
  font-size: clamp(2rem, 5vw, 3rem);
}

.placar-leitura {
  color: var(--roxo-escuro);
  font-size: 1.4rem;
  font-weight: 900;
}

.resultado-leitura > p:not(.placar-leitura) {
  max-width: 650px;
}

.botoes-resultado-leitura {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: center;
  margin-top: 14px;
}

@media (max-width: 650px) {
  .topo {
    grid-template-columns: 42px 1fr;
  }

  .progresso-resumo {
    display: none;
  }

  .acoes-topo {
    justify-self: end;
  }

  .limpar-progresso {
    font-size: 0;
  }

  .limpar-progresso::after {
    content: 'Limpar';
    font-size: 0.72rem;
  }

  .seletor-alunos {
    grid-template-columns: 1fr;
  }

  .cartao-aluno {
    min-height: 135px;
  }

  .cabecalho-revisao img {
    display: none;
  }

  .cartao-conteudo,
  .cartao-atividade,
  .cartao-desenho {
    grid-template-columns: 1fr;
  }

  .numero-etapa {
    width: 44px;
    height: 44px;
    border-radius: 14px;
  }

  .area-desenho {
    height: 280px;
  }

  .painel-progresso-mariana {
    top: 76px;
  }

  .cabecalho-etapa-mariana {
    align-items: flex-start;
  }

  .cabecalho-etapa-mariana .icone-etapa,
  .cabecalho-etapa-mariana > .solido-visual {
    display: none;
  }

  .blocos-revisao,
  .grade-solidos,
  .moldes,
  .simulado,
  .grupos-ordem {
    grid-template-columns: 1fr;
  }

  .numeros-extenso {
    grid-template-columns: repeat(2, 1fr);
  }

  .campo-mariana {
    grid-template-columns: 1fr;
  }

  .campo-resposta-ditado {
    grid-template-columns: 1fr;
  }

  .controles-ditado-gramatica button {
    flex: 1 1 170px;
  }

  .corrida-mariana {
    grid-template-columns: repeat(3, 1fr);
  }

  .canvas-mariana,
  .canvas-grande {
    height: 330px;
  }

  .navegacao-etapas {
    position: sticky;
    bottom: 8px;
  }

  .tela-gramatica-mariana .navegacao-etapas {
    position: static;
  }

  .cabecalho-biblioteca,
  .cabecalho-leitor {
    align-items: stretch;
    flex-direction: column;
  }

  .cartao-livro {
    grid-template-columns: 1fr;
  }

  .cartao-livro > img {
    min-height: 0;
    aspect-ratio: 1.414 / 1;
    padding: 10px;
  }

  .ir-para-pagina {
    width: 100%;
    margin-left: 0;
  }

  .botao-destaque-leitor {
    width: 100%;
  }

  .ir-para-pagina label {
    flex: 1;
  }

  .recipiente-canvas-livro {
    min-height: 210px;
    padding: 6px;
  }

  .explicacao-final-leitura {
    grid-template-columns: 1fr;
    padding: 20px;
  }

  .navegacao-paginas-leitura,
  .navegacao-questionario-leitura {
    align-items: stretch;
    flex-direction: column;
  }

  .navegacao-paginas-leitura button,
  .navegacao-questionario-leitura button {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* Cena Matemática Interativa */
.cartao-centenas {
  border-color: #e2a51f;
  background: linear-gradient(145deg, #fff8d8, #f1ecff);
}

.tela-matematica-cena {
  width: min(1180px, calc(100% - 24px));
  margin-inline: auto;
  padding-bottom: 28px;
}

.painel-progresso-centenas {
  border-color: #d6c6ff;
  background: rgba(255, 253, 248, 0.96);
}

.apresentacao-centenas,
.final-centenas,
.etapa-centenas {
  padding: clamp(22px, 5vw, 48px);
  border: 3px solid #d9ceff;
  border-radius: 30px;
  background: var(--papel);
  box-shadow: var(--sombra);
}

.apresentacao-centenas,
.final-centenas {
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.apresentacao-centenas h1,
.final-centenas h1,
.etapa-centenas h1 {
  margin: 4px 0 12px;
  color: var(--roxo-escuro);
  font-size: clamp(1.8rem, 5vw, 3rem);
  line-height: 1.08;
}

.passos-interacao {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin: 28px 0;
}

.passos-interacao span {
  display: flex;
  min-height: 112px;
  padding: 16px;
  border: 2px solid #d9ceff;
  border-radius: 20px;
  align-items: center;
  flex-direction: column;
  justify-content: center;
  background: #f7f3ff;
  font-weight: 800;
}

.passos-interacao strong {
  display: grid;
  width: 38px;
  height: 38px;
  margin-bottom: 7px;
  border-radius: 50%;
  place-items: center;
  color: white;
  background: var(--roxo);
}

.celebracao-matematica {
  display: inline-grid;
  width: 86px;
  height: 86px;
  border-radius: 50%;
  place-items: center;
  color: #5a3d00;
  background: var(--amarelo);
  font-size: 3rem;
  animation: celebrar-matematica 600ms ease-out both;
}

@keyframes celebrar-matematica {
  from {
    transform: scale(0.75) rotate(-8deg);
  }
  to {
    transform: scale(1) rotate(0);
  }
}

.resumo-final-centenas {
  max-width: 620px;
  margin: 24px auto;
  padding: 18px;
  border-radius: 18px;
  background: #eefaf4;
}

.resumo-final-centenas strong {
  color: #245d43;
  font-size: 1.4rem;
}

.etapa-centenas > header {
  max-width: 850px;
  margin: 0 auto 20px;
  text-align: center;
}

.cena-matematica {
  max-width: 1050px;
  margin: 0 auto;
  border: 2px solid #d9ceff;
  border-radius: 24px;
  overflow: hidden;
  background: #fff;
}

.cena-instrucao {
  padding: 20px clamp(16px, 4vw, 30px);
  color: #272046;
  background: linear-gradient(110deg, #eee8ff, #fff5ca);
}

.cena-instrucao h2 {
  margin: 2px 0 4px;
  font-size: clamp(1.35rem, 4vw, 2rem);
}

.cena-instrucao p:last-child {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 700;
}

.cena-area-construcao {
  min-height: 300px;
  padding: clamp(16px, 4vw, 28px);
  background-color: #fffcf4;
  background-image: radial-gradient(#ded6f7 1px, transparent 1px);
  background-size: 18px 18px;
}

.matematica-bandeja,
.cartoes-parcelas,
.cartoes-sequencia,
.fichas-dinheiro,
.escolhas-matematicas,
.trocas-matematicas {
  display: flex;
  gap: 12px;
  align-items: stretch;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 20px;
}

.ferramenta-matematica,
.cartoes-parcelas button,
.cartoes-sequencia button,
.escolhas-matematicas button,
.trocas-matematicas button {
  min-width: 92px;
  min-height: 52px;
  padding: 10px 14px;
  border: 2px solid #7d63d3;
  border-radius: 16px;
  background: white;
  cursor: pointer;
  font-weight: 900;
  touch-action: none;
}

.ferramenta-matematica {
  display: grid;
  min-width: 145px;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: center;
  text-align: left;
}

.ferramenta-matematica[aria-pressed='true'],
.cartoes-parcelas button[aria-pressed='true'],
.cartoes-sequencia button[aria-pressed='true'],
.escolhas-matematicas button[aria-pressed='true'],
.reta-numerica button[aria-pressed='true'] {
  border-color: var(--roxo-escuro);
  background: #e8e0ff;
  box-shadow: 0 0 0 4px rgba(101, 70, 196, 0.16);
}

.peca-dourada {
  position: relative;
  display: inline-block;
  flex: 0 0 auto;
  min-width: 44px;
  min-height: 44px;
  padding: 0;
  border: 2px solid #8c5f12;
  border-radius: 8px;
  background-color: #ffc94f;
  background-image:
    linear-gradient(#a97317 1px, transparent 1px),
    linear-gradient(90deg, #a97317 1px, transparent 1px);
  background-size: 10px 10px;
  box-shadow: 2px 3px 0 #bd7d19;
  cursor: pointer;
  touch-action: none;
}

.peca-dourada.peca-u {
  width: 44px;
  height: 44px;
}

.peca-dourada.peca-d {
  width: 44px;
  height: 82px;
}

.peca-dourada.peca-c {
  width: 76px;
  height: 76px;
}

.peca-dourada.peca-m {
  width: 84px;
  height: 84px;
  border-width: 4px;
  box-shadow: 7px 8px 0 #bd7d19;
}

.arrastando {
  z-index: 30;
  opacity: 0.82;
  pointer-events: none;
}

.quadro-ordens-matematico,
.abaco-matematico {
  display: grid;
  grid-template-columns: repeat(var(--colunas-matematica, auto-fit), minmax(132px, 1fr));
  gap: 10px;
  width: 100%;
}

.coluna-ordem {
  display: grid;
  min-width: 0;
  min-height: 280px;
  padding: 12px;
  border: 3px solid #846bd3;
  border-radius: 18px;
  align-content: start;
  justify-items: center;
  background: rgba(255, 255, 255, 0.94);
}

.coluna-ordem > strong {
  display: grid;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  place-items: center;
  color: white;
  background: var(--roxo-escuro);
  font-size: 1.3rem;
}

.nome-ordem {
  min-height: 28px;
  margin: 4px 0 8px;
  font-size: 0.83rem;
  font-weight: 800;
}

.pecas-na-ordem,
.haste-abaco {
  position: relative;
  display: flex;
  width: 100%;
  min-height: 132px;
  gap: 5px;
  align-content: flex-start;
  align-items: flex-end;
  flex-wrap: wrap;
  justify-content: center;
  padding: 9px;
  border: 2px dashed #b7a9e6;
  border-radius: 12px;
  background: #faf8ff;
}

.area-colocar-na-ordem {
  position: absolute;
  z-index: 0;
  inset: 0;
  width: 100%;
  min-height: 100%;
  padding: 0;
  border: 0;
  border-radius: 10px;
  background: transparent;
  cursor: pointer;
}

.area-colocar-na-ordem:focus-visible {
  outline: 4px solid #4f2daf;
  outline-offset: -5px;
}

.pecas-na-ordem.pronta-para-colocar,
.haste-abaco.pronta-para-colocar {
  border-color: #4f2daf;
  background: #f0ebff;
  box-shadow: inset 0 0 0 3px rgba(79, 45, 175, 0.12);
}

.pecas-na-ordem > .peca-dourada,
.haste-abaco > .argola-abaco {
  z-index: 1;
}

.haste-abaco {
  position: relative;
  align-content: end;
  align-items: center;
  flex-direction: column-reverse;
  flex-wrap: nowrap;
  justify-content: flex-start;
  background:
    linear-gradient(90deg, transparent 47%, #875522 47%, #875522 53%, transparent 53%), #faf8ff;
}

.argola-abaco {
  z-index: 1;
  width: 72px;
  min-height: 19px;
  border: 4px solid #8d3f75;
  border-radius: 50%;
  background: #ff95bd;
  cursor: pointer;
  touch-action: none;
}

.colocar-na-ordem {
  width: 100%;
  min-height: 46px;
  margin-top: 10px;
  border: 2px solid #6950bf;
  border-radius: 12px;
  color: #352278;
  background: #eee8ff;
  cursor: pointer;
  font-weight: 900;
}

.quantidade-ordem {
  display: grid;
  min-width: 36px;
  min-height: 36px;
  margin-top: 8px;
  border-radius: 50%;
  place-items: center;
  color: white;
  background: #3f3472;
  font-weight: 900;
}

.zona-remover {
  min-height: 52px;
  margin-top: 18px;
  padding: 13px;
  border: 2px dashed #a13d58;
  border-radius: 14px;
  color: #7b2138;
  background: #fff0f4;
  text-align: center;
  font-weight: 800;
}

.trocas-matematicas {
  margin-top: 16px;
}

.trocas-matematicas button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.destino-parcelas,
.linha-sequencia {
  display: flex;
  min-height: 105px;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  padding: 18px;
  border: 3px dashed #7a62ca;
  border-radius: 20px;
  background: white;
}

.conexao-numero-palavras {
  display: flex;
  max-width: 680px;
  gap: 14px;
  align-items: center;
  justify-content: center;
  margin: 0 auto 18px;
  padding: 14px;
  border: 2px solid #d1c4f8;
  border-radius: 16px;
  background: white;
  text-align: center;
}

.conexao-numero-palavras strong {
  color: var(--roxo-escuro);
  font-size: 1.7rem;
}

.conexao-numero-palavras span {
  font-weight: 800;
}

.destino-parcelas button,
.espaco-sequencia,
.numero-sequencia {
  display: grid;
  min-width: 68px;
  min-height: 52px;
  padding: 8px 12px;
  border: 2px solid #6950bf;
  border-radius: 13px;
  place-items: center;
  background: #f0ebff;
  font-size: 1.15rem;
  font-weight: 900;
}

.destino-parcelas .colocar-parcela {
  color: white;
  background: var(--roxo);
}

.linha-sequencia > span[aria-hidden='true'] {
  color: #58458f;
  font-size: 1.5rem;
  font-weight: 900;
}

.reta-numerica {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, minmax(58px, 1fr));
  width: 100%;
  max-width: 850px;
  gap: 5px;
  margin: 50px auto 20px;
  padding-top: 14px;
  border-top: 6px solid #514087;
}

.reta-numerica button {
  position: relative;
  min-height: 54px;
  border: 2px solid #6e58b9;
  border-radius: 12px;
  background: white;
  cursor: pointer;
  font-weight: 900;
}

.reta-numerica button > span {
  position: absolute;
  top: -24px;
  left: 50%;
  width: 5px;
  height: 18px;
  background: #514087;
}

.fichas-dinheiro button {
  display: flex;
  min-width: 150px;
  min-height: 86px;
  padding: 10px 16px;
  border: 3px solid #347155;
  border-radius: 16px;
  align-items: center;
  flex-direction: column;
  justify-content: center;
  color: #173f2e;
  background: repeating-linear-gradient(135deg, #e2f7eb, #e2f7eb 8px, #d4f0e0 8px, #d4f0e0 16px);
  cursor: pointer;
}

.fichas-dinheiro strong {
  font-size: 1.35rem;
}

.fichas-dinheiro small {
  font-weight: 700;
}

.dinheiro-escolhido {
  display: flex;
  min-height: 100px;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  padding: 16px;
  border: 2px dashed #347155;
  border-radius: 16px;
  background: white;
}

.dinheiro-escolhido button {
  min-height: 48px;
  padding: 8px 13px;
  border: 2px solid #347155;
  border-radius: 12px;
  color: #173f2e;
  background: #e2f7eb;
  cursor: pointer;
  font-weight: 900;
}

.grafico-matematico {
  display: grid;
  grid-template-columns: repeat(3, minmax(90px, 1fr));
  gap: 18px;
  max-width: 700px;
  min-height: 310px;
  margin: 0 auto 24px;
}

.barra-matematica {
  display: grid;
  gap: 7px;
  align-content: end;
  justify-items: center;
}

.barra-visual {
  display: flex;
  width: min(90px, 80%);
  height: 210px;
  align-items: flex-end;
  border-bottom: 4px solid #4e3e80;
}

.barra-visual span {
  width: 100%;
  height: calc(var(--valor-barra) * 10%);
  max-height: 100%;
  border: 3px solid #4f3e87;
  border-bottom: 0;
  border-radius: 10px 10px 0 0;
  background: #8fd6ef;
  transition: height 180ms ease;
}

.barra-matematica button {
  width: 48px;
  height: 48px;
  border: 2px solid #5b4797;
  border-radius: 12px;
  background: white;
  cursor: pointer;
  font-size: 1.4rem;
  font-weight: 900;
}

.tabela-matematica {
  width: min(100%, 520px);
  margin: 0 auto;
  border-collapse: collapse;
  background: white;
}

.tabela-matematica caption {
  padding: 8px;
  font-weight: 900;
}

.tabela-matematica th,
.tabela-matematica td {
  padding: 9px 12px;
  border: 2px solid #7460b8;
  text-align: left;
}

.mini-simulado-matematico {
  display: grid;
  max-width: 750px;
  gap: 14px;
  margin: 0 auto;
}

.mini-simulado-matematico label {
  display: grid;
  grid-template-columns: 1fr minmax(100px, 170px);
  gap: 12px;
  align-items: center;
  padding: 16px;
  border: 2px solid #d2c5fa;
  border-radius: 16px;
  background: white;
  font-weight: 800;
}

.mini-simulado-matematico input {
  width: 100%;
  min-height: 50px;
  border: 2px solid #6852b4;
  border-radius: 12px;
  text-align: center;
  font-size: 1.2rem;
  font-weight: 900;
}

.resumo-cena {
  margin: 0;
  padding: 14px 20px;
  color: #272046;
  background: #eee8ff;
  text-align: center;
  font-size: 1.05rem;
  font-weight: 900;
}

.controles-cena {
  display: flex;
  gap: 10px;
  align-items: stretch;
  flex-wrap: wrap;
  justify-content: center;
  padding: 16px 18px;
}

.controles-cena button {
  min-height: 50px;
  padding: 10px 16px;
  border: 2px solid #5f49ab;
  border-radius: 14px;
  background: white;
  cursor: pointer;
  font-weight: 900;
}

.controles-cena button.botao-principal {
  color: white;
  background: var(--roxo);
}

.controles-cena button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.matematica-feedback {
  min-height: 58px;
  margin: 0;
  padding: 14px 20px;
  border-top: 2px solid #ded5fa;
  text-align: center;
  font-weight: 800;
}

.matematica-feedback.sucesso {
  color: #174f35;
  background: #dff7e9;
}

.matematica-feedback.tente-novamente {
  color: #6b3511;
  background: #fff1d9;
}

.matematica-feedback.dica {
  color: #2e2760;
  background: #eee8ff;
}

@media (max-width: 720px) {
  .tela-matematica-cena {
    width: min(100% - 12px, 1180px);
  }

  .apresentacao-centenas,
  .final-centenas,
  .etapa-centenas {
    padding: 18px 10px;
    border-radius: 20px;
  }

  .passos-interacao {
    grid-template-columns: 1fr;
  }

  .passos-interacao span {
    min-height: 80px;
  }

  .cena-area-construcao {
    min-height: 250px;
    padding: 12px 7px;
  }

  .quadro-ordens-matematico,
  .abaco-matematico {
    gap: 5px;
    grid-template-columns: repeat(auto-fit, minmax(76px, 1fr));
  }

  .coluna-ordem {
    min-height: 230px;
    padding: 7px 4px;
    border-width: 2px;
  }

  .nome-ordem {
    font-size: 0.7rem;
  }

  .pecas-na-ordem,
  .haste-abaco {
    min-height: 106px;
    padding: 4px;
  }

  .peca-dourada.peca-d {
    height: 62px;
  }

  .peca-dourada.peca-c {
    width: 58px;
    height: 58px;
  }

  .peca-dourada.peca-m {
    width: 62px;
    height: 62px;
  }

  .argola-abaco {
    width: 54px;
  }

  .colocar-na-ordem {
    min-height: 48px;
    padding: 4px;
    font-size: 0.75rem;
  }

  .ferramenta-matematica {
    min-width: 130px;
    flex: 1 1 130px;
  }

  .reta-numerica {
    gap: 3px;
  }

  .reta-numerica button {
    min-width: 0;
    padding-inline: 2px;
    font-size: 0.78rem;
  }

  .grafico-matematico {
    gap: 5px;
  }

  .mini-simulado-matematico label {
    grid-template-columns: 1fr;
  }

  .controles-cena button {
    flex: 1 1 45%;
  }

  .navegacao-centenas button {
    flex: 1 1 0;
    min-width: 0;
    padding-inline: 9px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .celebracao-matematica {
    animation: none;
  }

  .barra-visual span {
    transition: none;
  }
}

/* Optional English subitems: each relationship keeps its own reversible controls. */
.ingles-interacoes {
  display: block;
  width: 100%;
  min-width: 0;
}
.ingles-interacoes fieldset {
  min-width: 0;
  margin: 1rem 0;
  padding: 1rem;
  border: 2px solid #8aa2b7;
  border-radius: 16px;
}
.ingles-interacoes legend {
  font-weight: 700;
  padding: 0 0.4rem;
}
.ingles-interacoes img {
  display: block;
  width: 100%;
  max-width: 480px;
  height: auto;
  margin: 0.6rem auto;
}
.ingles-interacoes .ingles-opcoes-subitem {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 160px), 1fr));
  gap: 0.65rem;
}
.ingles-interacoes .ingles-opcoes-subitem img {
  max-height: 155px;
  object-fit: contain;
}
.ingles-interacoes .alternativa-atividade-ingles {
  grid-template-columns: minmax(0, 1fr);
  gap: 4px;
  min-width: 0;
  min-height: 48px;
  overflow-wrap: anywhere;
}
.ingles-interacoes [aria-pressed='true'] {
  outline: 3px solid #285e91;
  background: #e5f3ff;
}
.ingles-interacoes [aria-invalid='true'] {
  border-color: #ad3535;
}
.ingles-interacoes input,
.ingles-interacoes select {
  display: block;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-height: 48px;
  padding: 0.7rem;
  font: inherit;
}
.ingles-interacoes table {
  width: 100%;
  border-collapse: collapse;
  margin: 1rem 0;
  table-layout: fixed;
}
.ingles-interacoes th,
.ingles-interacoes td {
  padding: 0.6rem;
  border: 1px solid #839bb0;
  overflow-wrap: anywhere;
  text-align: left;
}
.ingles-interacoes caption,
.ingles-interacoes summary {
  font-weight: 700;
  padding: 0.6rem;
}
.ingles-interacoes details {
  border-radius: 12px;
  background: #eff6ef;
  padding: 0.7rem;
}
.ingles-interacoes button:focus-visible,
.ingles-interacoes input:focus-visible,
.ingles-interacoes select:focus-visible {
  outline: 3px solid #79429b;
  outline-offset: 3px;
}
#ingles-modos-estudo {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin: 1rem 0;
}
#ingles-modos-estudo[hidden] {
  display: none;
}

#ingles-cartao-questao.interacoes-multiplas.com-apoio-visual {
  display: block;
}
.interacoes-multiplas .imagens-enunciado-ingles img {
  width: min(100%, 640px);
  height: auto;
  max-width: 100%;
  max-height: none;
  padding: 0;
}

