(function () {
  'use strict';

  var memoria = Object.create(null);
  var avisosEmitidos = Object.create(null);

  function copiar(valor) {
    return JSON.parse(JSON.stringify(valor));
  }

  function objeto(valor) {
    return valor && typeof valor === 'object' && !Array.isArray(valor) ? valor : {};
  }

  function avisarUmaVez(operacao, erro) {
    if (avisosEmitidos[operacao]) {
      return;
    }
    avisosEmitidos[operacao] = true;
    console.warn(
      'O armazenamento permanente está indisponível; o progresso será mantido nesta aba.',
      erro
    );
  }

  function lerTexto(chave) {
    try {
      var valor = window.localStorage.getItem(chave);
      return valor == null ? memoria[chave] || null : valor;
    } catch (erro) {
      avisarUmaVez('leitura', erro);
      return memoria[chave] || null;
    }
  }

  function gravarTexto(chave, valor) {
    memoria[chave] = valor;
    try {
      window.localStorage.setItem(chave, valor);
      return true;
    } catch (erro) {
      avisarUmaVez('gravação', erro);
      return false;
    }
  }

  function removerTexto(chave) {
    delete memoria[chave];
    try {
      window.localStorage.removeItem(chave);
      return true;
    } catch (erro) {
      avisarUmaVez('remoção', erro);
      return false;
    }
  }

  function analisar(texto, chave) {
    if (!texto) {
      return null;
    }
    try {
      return JSON.parse(texto);
    } catch (erro) {
      console.warn(
        'O progresso salvo em "' + chave + '" contém JSON inválido e foi ignorado.',
        erro
      );
      return null;
    }
  }

  function normalizarComSeguranca(configuracao, valor) {
    var base = copiar(configuracao.padrao);
    if (typeof configuracao.normalizar !== 'function') {
      return Object.assign(base, objeto(valor));
    }
    try {
      return configuracao.normalizar(valor, base);
    } catch (erro) {
      console.warn(
        'O progresso salvo em "' + configuracao.chave + '" não pôde ser normalizado.',
        erro
      );
      return base;
    }
  }

  function procurarLegado(configuracao) {
    var legados = Array.isArray(configuracao.legados) ? configuracao.legados : [];
    for (var indice = 0; indice < legados.length; indice += 1) {
      var legado = legados[indice];
      var dados = analisar(lerTexto(legado.chave), legado.chave);
      if (dados == null) {
        continue;
      }
      try {
        return typeof legado.migrar === 'function' ? legado.migrar(dados) : dados;
      } catch (erro) {
        console.warn('A migração de "' + legado.chave + '" foi ignorada com segurança.', erro);
      }
    }
    return null;
  }

  function criar(configuracao) {
    if (!configuracao || !configuracao.chave || configuracao.padrao == null) {
      throw new Error('A chave e o estado padrão são obrigatórios para criar um armazenamento.');
    }

    function carregar() {
      var texto = lerTexto(configuracao.chave);
      var dados = analisar(texto, configuracao.chave);
      var veioDeLegado = false;

      if (dados == null && texto == null) {
        dados = procurarLegado(configuracao);
        veioDeLegado = dados != null;
      }

      var estado = normalizarComSeguranca(configuracao, dados);
      if (veioDeLegado) {
        gravarTexto(configuracao.chave, JSON.stringify(estado));
      }
      return estado;
    }

    function salvar(estado) {
      var normalizado = normalizarComSeguranca(configuracao, estado);
      gravarTexto(configuracao.chave, JSON.stringify(normalizado));
      return normalizado;
    }

    return {
      chave: configuracao.chave,
      carregar: carregar,
      salvar: salvar,
      remover: function () {
        return removerTexto(configuracao.chave);
      },
    };
  }

  window.ArmazenamentoRevisoes = {
    criar: criar,
    lerJSON: function (chave, padrao) {
      var dados = analisar(lerTexto(chave), chave);
      return dados == null ? copiar(padrao) : dados;
    },
    salvarJSON: function (chave, valor) {
      return gravarTexto(chave, JSON.stringify(valor));
    },
    remover: removerTexto,
  };
})();

(function () {
  'use strict';

  var sintetizador = window.speechSynthesis;
  var sequencia = 0;
  var ultimaSolicitacao = null;
  var solicitacaoAtiva = null;
  var vozes = [];
  var inicializado = false;

  function textoSeguro(valor, limite) {
    return String(valor || '')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, limite || 500);
  }

  function idiomaNormalizado(idioma) {
    var valor = textoSeguro(idioma, 20).toLowerCase();
    if (valor === 'en' || valor.indexOf('en-') === 0) return 'en-US';
    return 'pt-BR';
  }

  function unidadeNormalizada(configuracao) {
    var unidade = textoSeguro(
      configuracao && (configuracao.unidadeAudio || configuracao.unidadeDitado),
      20
    ).toLowerCase();
    if (unidade === 'frase') return 'frase';
    if (unidade === 'instrucao' || unidade === 'instrução') return 'instrucao';
    return 'palavra';
  }

  function atualizarVozes() {
    if (!sintetizador || typeof sintetizador.getVoices !== 'function') {
      vozes = [];
      return vozes;
    }
    vozes = sintetizador.getVoices().filter(function (voz) {
      return voz && voz.localService !== false;
    });
    return vozes;
  }

  function pontuarVoz(voz, idioma) {
    var linguagem = String(voz.lang || '').toLowerCase();
    var nome = String(voz.name || '').toLowerCase();
    var desejado = idioma.toLowerCase();
    var prefixo = desejado.split('-')[0];
    var pontos = 0;
    if (linguagem === desejado) pontos += 100;
    else if (linguagem.indexOf(prefixo + '-') === 0 || linguagem === prefixo) pontos += 60;
    if (/natural|neural/.test(nome)) pontos += 12;
    if (/microsoft|zira|aria|jenny|maria|daniel/.test(nome)) pontos += 5;
    if (voz.default) pontos += 2;
    return pontos;
  }

  function selecionarVoz(idioma) {
    atualizarVozes();
    return (
      vozes
        .map(function (voz) {
          return { voz: voz, pontos: pontuarVoz(voz, idioma) };
        })
        .filter(function (item) {
          return item.pontos >= 60;
        })
        .sort(function (a, b) {
          return b.pontos - a.pontos;
        })[0]?.voz || null
    );
  }

  function emitir(fase, mensagem, configuracao, extras) {
    var detalhe = Object.assign(
      {
        fase: fase,
        mensagem: mensagem,
        origem: configuracao && configuracao.origem ? configuracao.origem : 'geral',
        idioma: configuracao && configuracao.idioma ? configuracao.idioma : null,
        texto: configuracao && configuracao.texto ? configuracao.texto : null,
      },
      extras || {}
    );
    document.dispatchEvent(new CustomEvent('audioestadoalterado', { detail: detalhe }));
    if (configuracao && typeof configuracao.aoEstado === 'function') {
      configuracao.aoEstado(detalhe);
    }
  }

  function parar(opcoes) {
    opcoes = opcoes || {};
    var ativa = solicitacaoAtiva;
    sequencia += 1;
    solicitacaoAtiva = null;
    if (sintetizador && typeof sintetizador.cancel === 'function') sintetizador.cancel();
    if (ativa) {
      emitir('cancelado', 'Áudio interrompido.', ativa);
      return;
    }
    if (!opcoes.silencioso) {
      emitir('parado', 'Áudio interrompido.', { origem: opcoes.origem || 'geral' });
    }
  }

  function configurarFala(texto, idioma, velocidade, voz) {
    var fala = new window.SpeechSynthesisUtterance(texto);
    fala.lang = idioma;
    fala.rate = velocidade;
    fala.pitch = 1;
    fala.volume = 1;
    if (voz) fala.voice = voz;
    return fala;
  }

  function textoProtegido(texto, idioma, unidade) {
    if (idioma === 'en-US') return (unidade === 'frase' ? 'Phrase: ' : 'Word: ') + texto;
